    static boolean[][][][][] reach;
    static int[] dx = {-1, 0, 1, 0, 0};
    static int[] dy = {0, 1, 0, -1, 0};

    static boolean valid(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    static boolean digit(char c) {
        return c >= '0' && c <= '9';
    }

    static void bfs(int sx, int sy) {
        Queue<int[]> q = new LinkedList<>();
        dist[sx][sy] = 0;
        q.add(new int[]{sx, sy});
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1];
            for (int d = 0; d < 4; ++d) {
                int nx = x + dx[d], ny = y + dy[d];
                if (valid(nx, ny) && digit(grid1[nx][ny]) && dist[nx][ny] == 1000) {
                    dist[nx][ny] = dist[x][y] + 1;
                    q.add(new int[]{nx, ny});
                }
            }
        }
    }

    static class Edge {
        int to, rev, cap;
        Edge(int to, int rev, int cap) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
        }
    }

    static void addEdge(ArrayList<ArrayList<Edge>> graph, int from, int to, int cap) {
        graph.get(from).add(new Edge(to, graph.get(to).size(), cap));
        graph.get(to).add(new Edge(from, graph.get(from).size() - 1, 0));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        sc.nextLine(); // consume newline
        grid1 = new char[n][n];
        grid2 = new char[n][n];
        for (int i = 0; i < n; ++i) {
            String line = sc.nextLine();
            grid1[i] = line.toCharArray();
        }
        for (int i = 0; i < n; ++i) {
            String line = sc.nextLine();
            grid2[i] = line.toCharArray();
        }

        // init dist
        dist = new int[n][n];
        for (int i = 0; i < n; ++i)
            Arrays.fill(dist[i], 1000);

        // find start
        int sx = -1, sy = -1;
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (grid1[i][j] == 'Z') {
                    sx = i;
                    sy = j;
                }

        bfs(sx, sy);

        // init reach
        reach = new boolean[t + 1][n][n][n][n];

        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                for (int d = 0; d < 5; ++d) {
                    int ni = i + dx[d], nj = j + dy[d];
                    if (valid(ni, nj) && digit(grid1[i][j]) && digit(grid1[ni][nj]))
                        reach[0][i][j][ni][nj] = true;
                }

        for (int k = 0; k <= t - 2; ++k)
            for (int i = 0; i < n; ++i)
                for (int j = 0; j < n; ++j)
                    for (int l = 0; l < n; ++l)
                        for (int m = 0; m < n; ++m) {
                            if (!reach[k][i][j][l][m]) continue;
                            for (int d = 0; d < 5; ++d) {
                                int nl = l + dx[d], nm = m + dy[d];
                                if (valid(nl, nm) && digit(grid1[nl][nm]) && dist[l][m] >= k + 2 && dist[nl][nm] >= k + 2)
                                    reach[k + 1][i][j][nl][nm] = true;
                            }
                        }

        List<int[]> cells = new ArrayList<>();
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (digit(grid1[i][j]))
                    cells.add(new int[]{i, j});

        int V = 2 * cells.size() + 2;
        ArrayList<ArrayList<Edge>> graph = new ArrayList<>(V);
        for (int i = 0; i < V; ++i)
            graph.add(new ArrayList<>());

        for (int i = 0; i < cells.size(); ++i) {
            int c1 = grid1[cells.get(i)[0]][cells.get(i)[1]] - '0';
            addEdge(graph, 0, i + 1, c1);
            int c2 = grid2[cells.get(i)[0]][cells.get(i)[1]] - '0';
            addEdge(graph, cells.size() + 1 + i, V - 1, c2);
        }

        for (int i = 0; i < cells.size(); ++i)
            for (int j = 0; j < cells.size(); ++j) {
                boolean ok = false;
                for (int k = 0; k <= t - 1; ++k)
                    if (reach[k][cells.get(i)[0]][cells.get(i)[1]][cells.get(j)[0]][cells.get(j)[1]]) {
                        ok = true;
                        break;
                    }
                if (ok) {
                    addEdge(graph, i + 1, cells.size() + 1 + j, 1000);
                }
