            for (int v = V - 1; v != 0; v = parent[v]) {
                int u = parent[v];
                for (Edge e : graph.get(u))
                    if (e.to == v) e.cap -= inc;
                for (Edge e : graph.get(v))
                    if (e.to == u) e.cap += inc;
            }
            flow += inc;
        }

        System.out.println(flow);
        sc.close();
    }
